@router.get("/api/v1/onboarding/wizard/{session_id}/state")
async def get_wizard_session_state(
    session_id: uuid.UUID,
    cache: Redis = Depends(get_redis_client),
    current_user: User = Depends(get_current_user)
):
    raw_state = await cache.get(f"wizard:onboarding:{session_id}")
    if not raw_state:
        raise HTTPException(status_code=404, detail="Onboarding session expired or not found")
    state = json.loads(raw_state)
    if state.get("user_id") != str(current_user.id):
        raise HTTPException(status_code=403, detail="Access to wizard session forbidden")
    return {
        "current_step": state.get("step"),
        "business_tin": state.get("tax_identification_number"),
        "bank_account_number": state.get("bank_account_number"),
        "beneficial_owners": state.get("beneficial_owners")
    }
